		desc := fmt.Sprintf("position:bl, offset:%.2f %.2f, scalefactor:1.0 abs, rotation:0, opacity:1", placed.minX, pdfY)
		wm, wmErr := api.ImageWatermarkForReader(bytes.NewReader(regionImg), desc, true, false, types.POINTS)
