func envOrDefault(key, fallback string) string {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	return value
}

func envInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil || parsed <= 0 {
		return fallback
	}
	return parsed
}

// envSeconds reads a duration given in whole seconds. These guards protect the
// server from connections that never finish, so a non-positive value falls back
// to the default instead of disabling them.
func envSeconds(key string, fallback time.Duration) time.Duration {
	return envDuration(key, fallback, time.Second, false)
}

// envDuration reads whole units using int64 on every architecture. Check the
// bound before multiplication: overflow can wrap to positive durations too.
// Only callers whose policy gives zero a meaning should set allowZero.
func envDuration(key string, fallback, unit time.Duration, allowZero bool) time.Duration {
	value := strings.TrimSpace(os.Getenv(key))
	parsed, err := strconv.ParseInt(value, 10, 64)
	if err != nil || parsed < 0 || (!allowZero && parsed == 0) || parsed > math.MaxInt64/int64(unit) {
		return fallback
	}
	return time.Duration(parsed) * unit
}

// envMebibytes reads a size given in whole mebibytes using int64 on every
// architecture. Check the bound before multiplication: a wrapped size would be
// negative or far smaller than asked for, and the upload guards that compare
// against it would then refuse every upload instead of raising the cap.
func envMebibytes(key string, fallbackMB int64) int64 {
	const mebibyte = 1024 * 1024
	value := strings.TrimSpace(os.Getenv(key))
	parsed, err := strconv.ParseInt(value, 10, 64)
	if err != nil || parsed <= 0 || parsed > math.MaxInt64/mebibyte {
		return fallbackMB * mebibyte
	}
	return parsed * mebibyte
}

// envNonNegativeInt accepts an explicit 0, which callers use to turn a limit off.
func envNonNegativeInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil || parsed < 0 {
		return fallback
	}
	return parsed
}

