// historyLimit turns the caller supplied page size into a bounded one. A missing,
// unparsable or non-positive value falls back to the default page, and anything
// larger than the maximum is capped so a single request cannot make the server
// clone and serialize every job it still holds.
func historyLimit(raw string) int {
	parsed, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil || parsed <= 0 {
		return defaultHistoryLimit
	}
	if parsed > maxHistoryLimit {
		return maxHistoryLimit
	}
	return parsed
}

func (s *Server) readProcessInput(w http.ResponseWriter, r *http.Request) (service.ProcessInput, error) {
	bodyLimit := s.config.Limits.MaxFileSizeBytes + uploadBodyHeadroomBytes
	r.Body = http.MaxBytesReader(w, r.Body, bodyLimit)
	if err := r.ParseMultipartForm(uploadMemoryBytes); err != nil {
		var maxBytesErr *http.MaxBytesError
		if errors.As(err, &maxBytesErr) {
			return service.ProcessInput{}, &payloadTooLargeError{limit: bodyLimit}
		}
		return service.ProcessInput{}, fmt.Errorf("invalid multipart form: %w", err)
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		return service.ProcessInput{}, fmt.Errorf("file field is required")
	}
	defer file.Close()

	content, err := io.ReadAll(io.LimitReader(file, s.config.Limits.MaxFileSizeBytes+1))
	if err != nil {
		return service.ProcessInput{}, fmt.Errorf("failed to read uploaded file: %w", err)
	}

	attachment := document.NewAttachment(header.Filename, header.Header.Get("Content-Type"), content)
	options := upstage.ParseOptions{
		Model:   strings.TrimSpace(r.FormValue("model")),
		Lang:    strings.TrimSpace(r.FormValue("lang")),
		Schema:  strings.TrimSpace(r.FormValue("schema")),
		Verbose: strings.EqualFold(strings.TrimSpace(r.FormValue("verbose")), "true"),
	}

	return service.ProcessInput{
		Attachment: attachment,
		Options:    options,
